/**
 * pi-claude-conversion — Claude Code CLI tool-name and parameter parity for pi.
 *
 * When the active provider is claude-bridge (Anthropic/Claude), this extension:
 *   1. Activates CC Title-Case tool aliases (Read, Write, Edit, Grep, Find, LS)
 *      so the CC-trained model sees the names it was trained on.
 *   2. Exposes WebFetch and WebSearch with CC parameter shapes.
 *   3. Keeps bash/bash_output/bash_kill active (pi native names match CC).
 *   4. Deactivates pi lowercase names (read, write, edit, grep, find, ls)
 *      and all pi-codex-conversion tool names to avoid duplication.
 *
 * When the provider is openai-codex, this extension is a no-op.
 * pi-codex-conversion handles the Codex tool surface independently.
 *
 * Cache-stability contract (pi-dev.md):
 *   - All TypeBox schemas live at module-level, declared once, never mutated.
 *   - setActiveTools is guarded to only fire when the tool-name set changes.
 *   - No dynamic content injected into params.system.
 *   - Web tools are registered eagerly (small footprint, required on first turn).
 *
 * Sibling session alignment:
 *   - Base branch: fix/pi-workflow-missing-module (f6a9fe98)
 *   - sibling pi/worktree/pi-goal-cc-parity worked on pi-goal verifier, not tool names.
 *   - No conflicts expected; this extension is wholly new.
 */

import type { ExtensionAPI } from "@valkyriweb/pi-coding-agent";
import { syncCCAdapter, type CCAdapterState } from "./activation.ts";
import { registerCCFileTools } from "./tools/cc-file-tools.ts";
import { registerCCWebTools } from "./tools/cc-web-tools.ts";
import { registerCCBashTool } from "./tools/cc-bash-tool.ts";
import { registerCCGlobTool } from "./tools/cc-glob-tool.ts";
import { rewriteCCProviderRequest } from "./provider-request.ts";

export default function piClaudeConversion(pi: ExtensionAPI): void {
	const state: CCAdapterState = {
		enabled: false,
		previousToolNames: [],
	};

	// Register all CC-aliased tools once at startup.
	// They are registered but NOT active by default — activation is gated on
	// claude-bridge model detection in syncCCAdapter.
	registerCCBashTool(pi);
	registerCCFileTools(pi);
	registerCCGlobTool(pi);
	registerCCWebTools(pi);

	pi.on("session_start", async (_event, ctx) => {
		syncCCAdapter(pi, ctx, state);
	});

	pi.on("model_select", async (_event, ctx) => {
		syncCCAdapter(pi, ctx, state);
	});

	// Cache-fix patch #2: assign shape-aware cache key after native tool rewrites.
	// This hook fires AFTER the bridge has rewritten any provider-native tools
	// (WebFetch/WebSearch → Anthropic-native tool_reference shapes), so the
	// hash reflects the actual wire payload.
	// BeforeProviderRequestEventResult = unknown; return the rewritten payload
	// for Pi to use, or undefined to let Pi use the original.
	pi.on("before_provider_request", async (event, ctx) => {
		const payload = (event as { payload?: unknown }).payload;
		if (!payload) return undefined;
		return rewriteCCProviderRequest(payload, ctx, state) ?? undefined;
	});

	pi.on("session_shutdown", async () => {
		// State is reset per-session; nothing persistent to clean up.
		state.enabled = false;
		state.previousToolNames = [];
	});
}

