/**
 * Adapter activation — enable/disable CC tool aliases based on active model.
 *
 * Cache-stability rules (pi-dev.md footguns):
 * - setActiveTools is guarded: only called when the tool-name set actually changes.
 * - tools[] declared via registerTool (TypeBox schemas) are byte-stable.
 * - Dynamic data (status lines) goes to ctx.ui.setStatus, not system prompt.
 */

import type { ExtensionAPI, ExtensionContext } from "@valkyriweb/pi-coding-agent";
import { isClaudeBridgeModel, isOpenAICodexModel } from "./cc-model.ts";
import {
	CC_ADAPTER_TOOL_NAMES,
	CODEX_OWNED_TOOL_NAMES,
	PI_NATIVE_LOWERCASE_NAMES,
	STATUS_KEY,
	STATUS_TEXT,
} from "./tool-set.ts";
import { applyDeferredAdapterTools, clearDeferredAdapterTools } from "./provider-request.ts";

export interface CCAdapterState {
	enabled: boolean;
	previousToolNames: string[];
}

function setActiveToolsIfChanged(pi: ExtensionAPI, toolNames: string[]): void {
	const current = pi.getActiveTools();
	if (
		current.length === toolNames.length &&
		current.every((name, i) => name === toolNames[i])
	) {
		return;
	}
	pi.setActiveTools(toolNames);
}

/**
 * Build the desired active tool list for claude-bridge:
 * - Include CC_ADAPTER_TOOL_NAMES
 * - Preserve any extension tools not owned by codex or the pi lowercase set
 * - Remove pi lowercase names (replaced by Title-Case CC aliases)
 * - Remove codex-owned tools (pi-codex-conversion owns those)
 */
function buildCCActiveTools(currentActive: string[]): string[] {
	const owned = new Set([...CC_ADAPTER_TOOL_NAMES, ...PI_NATIVE_LOWERCASE_NAMES, ...CODEX_OWNED_TOOL_NAMES]);
	const preserved = currentActive.filter((n) => !owned.has(n));
	return [...CC_ADAPTER_TOOL_NAMES, ...preserved];
}

/**
 * Restore the tool set when leaving claude-bridge:
 * - Restore previously saved tools + pi lowercase names
 * - Strip CC Title-Case aliases
 */
function buildRestoredTools(previousTools: string[], currentActive: string[]): string[] {
	const ccOwned = new Set(CC_ADAPTER_TOOL_NAMES);
	const preserved = currentActive.filter((n) => !ccOwned.has(n));
	const restored = previousTools.filter((n) => !ccOwned.has(n));
	// merge: restored base + any non-CC tools that appeared while active
	for (const n of preserved) {
		if (!restored.includes(n)) restored.push(n);
	}
	return restored;
}

export function syncCCAdapter(pi: ExtensionAPI, ctx: ExtensionContext, state: CCAdapterState): void {
	const shouldEnable = isClaudeBridgeModel(ctx.model) && !isOpenAICodexModel(ctx.model);
	if (shouldEnable) {
		enableCCAdapter(pi, ctx, state);
	} else {
		disableCCAdapter(pi, ctx, state);
	}
}

function enableCCAdapter(pi: ExtensionAPI, ctx: ExtensionContext, state: CCAdapterState): void {
	if (!state.enabled) {
		state.previousToolNames = pi.getActiveTools();
		state.enabled = true;
	}
	const desired = buildCCActiveTools(pi.getActiveTools());
	setActiveToolsIfChanged(pi, desired);
	// Cache-fix patch #3: register deferred overrides after every setActiveTools
	applyDeferredAdapterTools(pi as Parameters<typeof applyDeferredAdapterTools>[0], CC_ADAPTER_TOOL_NAMES);
	if (ctx.hasUI) ctx.ui.setStatus(STATUS_KEY, STATUS_TEXT);
}

function disableCCAdapter(pi: ExtensionAPI, ctx: ExtensionContext, state: CCAdapterState): void {
	if (!state.enabled) {
		if (ctx.hasUI) ctx.ui.setStatus(STATUS_KEY, undefined);
		return;
	}
	const restored = buildRestoredTools(state.previousToolNames, pi.getActiveTools());
	setActiveToolsIfChanged(pi, restored);
	// Cache-fix patch #3: clear deferred overrides on disable
	clearDeferredAdapterTools(pi as Parameters<typeof clearDeferredAdapterTools>[0]);
	state.enabled = false;
	state.previousToolNames = [];
	if (ctx.hasUI) ctx.ui.setStatus(STATUS_KEY, undefined);
}

export function isCCAdapterActive(state: CCAdapterState): boolean {
	return state.enabled;
}

