console.log("→ Verifying cache-fix patch presence in source files...");
const providerRequestSrc = readFileSync(join(__dir, "src/provider-request.ts"), "utf8");
const activationSrc = readFileSync(join(__dir, "src/activation.ts"), "utf8");
const indexSrc = readFileSync(join(__dir, "src/index.ts"), "utf8");

// Patch 1: stableSnapshotHash function exists
assert.match(providerRequestSrc, /function stableSnapshotHash\(value: unknown\): string/, "stableSnapshotHash must be defined in provider-request.ts");
// Patch 1/2: ccPromptCacheKey derives cacheAffinityKey:shape:toolsHash
assert.match(providerRequestSrc, /function ccPromptCacheKey\(/, "ccPromptCacheKey must be defined");
assert.match(providerRequestSrc, /`\$\{cacheAffinityKey\}:shape:\$\{toolsHash\}`/, "ccPromptCacheKey must use cacheAffinityKey:shape:toolsHash format");
// Patch 2: before_provider_request hook registered in index
assert.match(indexSrc, /before_provider_request/, "index.ts must register before_provider_request hook");
// Patch 3: setDeferredOverrides called in activation
assert.match(activationSrc, /applyDeferredAdapterTools/, "activation.ts must call applyDeferredAdapterTools");
assert.match(activationSrc, /clearDeferredAdapterTools/, "activation.ts must call clearDeferredAdapterTools");
assert.match(providerRequestSrc, /setDeferredOverrides\?\.\(toolNames\)/, "provider-request.ts must call setDeferredOverrides");
assert.match(providerRequestSrc, /setDeferredOverrides\?\.\(\[\]\)/, "provider-request.ts must clear setDeferredOverrides");
console.log("  ✓ All three cache-fix patches present in source");

// ── (g) WebFetch/WebSearch exclusion from tool-search catalog ────────────────
// Design: WebFetch/WebSearch are excluded via CATALOG_EXCLUDE_EXACT in catalog.ts
// (NOT via FORCE_ALWAYS_ACTIVE, which capability-normalises names and would swallow
