assert.match(toolSearchCatalogSrc, /CATALOG_EXCLUDE_EXACT/, "catalog.ts must define CATALOG_EXCLUDE_EXACT");
assert.match(toolSearchCatalogSrc, /["']WebFetch["']/, "WebFetch must be in CATALOG_EXCLUDE_EXACT");
assert.match(toolSearchCatalogSrc, /["']WebSearch["']/, "WebSearch must be in CATALOG_EXCLUDE_EXACT");
