assert.match(toolSearchCatalogSrc, /CATALOG_EXCLUDE_EXACT\.has\(tool\.name\)/, "buildCatalog must check CATALOG_EXCLUDE_EXACT");
// Verify config.ts documents why they're NOT in FORCE_ALWAYS_ACTIVE
