// ── Load the extension ───────────────────────────────────────────────────────
console.log("→ Loading pi-claude-conversion extension...");
const handlers = { tools: {} };
const deferredOverrideCalls = [];
const setActiveCalls = [];
let currentActiveTools = [];

const api = {
  registerTool: (tool) => {
    assert(!handlers.tools[tool.name], `duplicate tool registration: ${tool.name}`);
    handlers.tools[tool.name] = tool;
  },
  on: (event, handler) => (handlers[event] = handler),
  getActiveTools: () => [...currentActiveTools],
  setActiveTools: (names) => {
    setActiveCalls.push([...names]);
    currentActiveTools = [...names];
  },
