const expectedTools = ["Bash", "Edit", "Find", "Glob", "Grep", "LS", "Read", "WebFetch", "WebSearch", "Write"].sort();
assert.deepEqual(registeredNames, expectedTools, `Expected tools: ${expectedTools.join(", ")}`);
