// setDeferredOverrides should have been called
assert.ok(deferredOverrideCalls.length > 0, "setDeferredOverrides must be called when CC adapter activates");
console.log(`  ✓ claude-bridge: CC tools active (${claudeActive.length} total)`);

// Idempotency: calling session_start again with the same model should be a no-op
const setCallsBeforeSecondSync = setActiveCalls.length;
await handlers.session_start({ type: "session_start" }, claudeCtx);
const callsAdded = setActiveCalls.length - setCallsBeforeSecondSync;
// The guard may still call setActiveTools if the tool set hasn't changed — acceptable
