console.log("  ✓ Idempotent sync: repeated session_start with same model is stable");

// Non-claude provider → CC adapter should be inactive
currentActiveTools = ["read", "bash", "edit", "write", "grep", "tool_search"];
setActiveCalls.length = 0;
deferredOverrideCalls.length = 0;
const nonClaudeCtx = {
  model: { provider: "openai-codex", api: "openai-codex-responses", id: "gpt-5" },
