};
await handlers.session_start({ type: "session_start" }, nonClaudeCtx);
const codexActive = currentActiveTools;
assert.ok(!codexActive.includes("Read"), "CC 'Read' must NOT be active for openai-codex");
assert.ok(!codexActive.includes("Glob"), "CC 'Glob' must NOT be active for openai-codex");
console.log(`  ✓ openai-codex: CC adapter is no-op`);

// ── (c) Byte-stability across two consecutive syncs ──────────────────────────
