setActiveCalls.length = 0;
await handlers.session_start({ type: "session_start" }, claudeCtx);
const firstSyncTools = [...currentActiveTools];
await handlers.session_start({ type: "session_start" }, claudeCtx);
const secondSyncTools = [...currentActiveTools];
assert.deepEqual(firstSyncTools, secondSyncTools, "tools[] must be byte-stable across two consecutive session_start syncs with same provider");
console.log("  ✓ tools[] is byte-stable across consecutive syncs");

// ── (d) Param translation: Bash ───────────────────────────────────────────────
console.log("→ Testing Bash param translation...");
const bashTool = handlers.tools["Bash"];
assert.ok(bashTool, "Bash tool must be registered");

// prepareArguments: normal params
const normalArgs = bashTool.prepareArguments({ command: "echo hello", timeout: 5000, run_in_background: false, description: "echo test" });
assert.equal(normalArgs.command, "echo hello", "command passthrough");
assert.equal(normalArgs.timeout, 5000, "timeout passthrough");
assert.equal(normalArgs.run_in_background, false, "run_in_background passthrough");
