// prepareArguments: run_in_background as string "true" (CC semanticBoolean)
const bgStringArgs = bashTool.prepareArguments({ command: "sleep 5", run_in_background: "true" });
assert.equal(bgStringArgs.run_in_background, true, "run_in_background='true' must be coerced to boolean true");

// prepareArguments: dangerouslyDisableSandbox=true → sentinel
