console.log("  ✓ Bash execute: echo hello works");

// execute: timeout
const timeoutResult = await bashTool.execute("call-3", { command: "sleep 10", timeout: 100 }, undefined, undefined, ctx);
assert.equal(timeoutResult.isError, true, "timed-out command must return isError:true");
assert.match(timeoutResult.content[0].text, /timed out|timeout/i, "timeout message");
console.log("  ✓ Bash execute: timeout triggers error");

