console.log("→ Testing Edit param translation...");
const editTool = handlers.tools["Edit"];
assert.ok(editTool, "Edit tool must be registered");

// Create a temp file to test Edit
import { tmpdir } from "node:os";
import { writeFileSync, readFileSync as rfs } from "node:fs";
import { join as pathJoin } from "node:path";
const tmpFile = pathJoin(tmpdir(), `pi-cc-edit-test-${Date.now()}.txt`);
