// --- Pi-native tools (upstream-aligned names, capitalized UI labels) ---
// Names match core's factories (read/edit/write/grep/Glob/ls/bash) so the
// extension tool overwrites the core builtin by registry key and the bridge presents
// CC-canonical casing on the wire. Display stays "Read"/"Bash"/... via ToolDefinition
// .label. Agent stays capitalized (core filters an extension tool named "agent" when
// the core "agent" builtin exists); TaskBackgroundList/TaskStop are runtime-task
// tools with no lowercase upstream form.

const LOAD_HOOK = "load";
const NATIVE_TOOL_NAMES = [
  "read",
  "bash",
  "TaskBackgroundList",
  "TaskStop",
  "edit",
  "write",
  "Agent",
  "grep",
  "Glob",
  "ls",
] as const;

// Core's Bash tool blocks `cd <cwd> && ...` with a "Blocked redundant cd" error to
// steer toward native tools / `-C` flags. Luke wants those to just run instead of
// erroring. We strip a leading redundant `cd <cwd>` (one that resolves to the session
// cwd) before core's guard sees the command, so it executes in cwd as intended. A cd
// to a *different* directory is left untouched (core already allows that). Done in the
// extension wrapper's prepareArguments so pi-mono-fork core stays at upstream shape.
const REDUNDANT_CD_PREFIX = /^(\s*cd\s+("[^"]+"|'[^']+'|(?:\\\S|\S)+)\s*(?:&&|;)\s*)(?=\S)/s;
function unquoteShellPath(value: string): string {
  if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
    return value.slice(1, -1);
  }
  return value.replace(/\\ /g, " ");
}
export function stripRedundantCd(command: string, cwd: string): string {
  const match = REDUNDANT_CD_PREFIX.exec(command);
  if (!match) return command;
  let target = unquoteShellPath(match[2]!);
  if (target === "~" || target.startsWith("~/")) target = join(homedir(), target.slice(2));
  if (resolve(cwd, target) !== resolve(cwd)) return command;
  return command.slice(match[1]!.length);
}

// Claude Code parity: a foreground `sleep N && cmd` chain burns the whole turn doing
// nothing, so CC's harness rejects it with a nudge toward Monitor until-loops and
// run_in_background. Mirror that block here. Only the LEADING command is checked —
// sleeps inside `until <check>; do sleep 2; done` loops stay allowed — and callers
// that pass run_in_background: true skip the guard entirely (a backgrounded wait IS
// the sanctioned path). Throwing from prepareArguments surfaces as a normal error
// tool result via the agent-loop catch, matching CC's "Error: Blocked: ..." shape.
const LEADING_SLEEP = /^\s*sleep\s+(\S+)\s*(?:(?:&&|;)\s*([\s\S]*))?$/;
const SLEEP_NUDGE =
  "To wait for a condition, use monitor_start with an until-loop (e.g. `until <check>; do sleep 2; done`). " +
  "To wait for a command you started, use run_in_background: true. " +
  "Do not chain shorter sleeps to work around this block.";
export function assertNoForegroundSleep(command: string): void {
  const match = LEADING_SLEEP.exec(command);
  if (!match) return;
  const rest = match[2]?.trim();
  throw new Error(
    rest
      ? `Blocked: sleep ${match[1]} followed by: ${rest}. ${SLEEP_NUDGE}`
      : `Blocked: foreground sleep ${match[1]}. ${SLEEP_NUDGE}`,
  );
}

// Background output footgun (recurring source of "my bg logs are empty"):
// spawnBashBackground writes the pipeline's combined stdout+stderr straight to a
// log fd, so the wrapper already captures everything. Piping a backgrounded
// command through a NON-follow `tail`/`head` defeats that — those filters buffer
// all input and only emit at EOF, so the bg log reads empty until the process
// exits, and the reader (TaskOutput) already shows a truncated tail anyway. We
// reject only the clear case: a trailing `| tail`/`| head` without -f/--follow on
// a run_in_background command. Standalone `tail -f log` (no preceding pipe) and
// every foreground command stay untouched. Mirrors assertNoForegroundSleep:
// throwing from prepareArguments surfaces as a normal "Error: Blocked: ..." result.
const BG_PIPE_FOLLOW = /(?:^|\s)(?:-f|-F|--follow)(?:[=\s]|$)/;
export function assertNoBufferingPipeInBackground(command: string): void {
  // Split on a single `|` that is not part of `||`, then inspect the last stage.
  const segments = command.split(/(?<!\|)\|(?!\|)/);
  if (segments.length < 2) return; // no pipe — not the footgun
  const last = segments[segments.length - 1]!.trim();
  const filter = /^(tail|head)\b/.exec(last)?.[1];
  if (!filter) return;
  if (BG_PIPE_FOLLOW.test(last)) return; // `tail -f`/`-F`/`--follow` streams — fine
  throw new Error(
    `Blocked: background command piped through \`${filter}\`. ` +
      "Background jobs capture full stdout+stderr to a log, and TaskOutput(task_id) already shows a truncated tail. " +
      `A non-follow \`${filter}\` buffers until the process exits, so the bg log reads empty while it runs. ` +
      `Drop the \`| ${filter}\` and read progress with TaskOutput(task_id).`,
  );
}

// Fragile `gh` PR/issue body construction (recurring "heredoc mangled the PR body"
// footgun). Supplying --body via a heredoc or a $(...) command substitution routes
// the body through the shell, where backticks and `$` inside the prose get expanded
// and a stray indent or harness re-wrap leaves the heredoc unterminated. A 45-day
// session scan found 214 gh pr/issue create|edit|comment calls building the body
// this way and 37 hard failures (unexpected EOF, bad substitution, command not
// found, No such file or directory) — each one a botched/duplicated PR body needing
// manual recovery. The reliable path is the Write tool + `--body-file`, which never
// touches the shell. We block only the fragile inline-body forms; `--body-file` and
// plain literal `--body "text"` pass through untouched. Mirrors assertNoForegroundSleep:
// throwing from prepareArguments surfaces as a normal "Error: Blocked: ..." result.
const GH_PR_ISSUE_BODY_CMD = /\bgh\s+(?:pr|issue)\s+(?:create|edit|comment)\b/;
const GH_HEREDOC = /<<-?\s*["']?[A-Za-z_]\w*/;
// A --body/--notes/-b value that starts a $(...) substitution or a backtick.
const GH_INLINE_BODY_SUBST = /(?:--body|--notes|-b)(?:=|\s+)["']?\s*(?:\$\(|`)/;
// A double-quoted --body/--notes/-b value containing a backtick (bash expands
// backticks inside double quotes), e.g. --body "see `gh` docs".
const GH_BODY_DQ_BACKTICK = /(?:--body|--notes|-b)(?:=|\s+)"[^"]*`/;
export function assertNoFragileGhBody(command: string): void {
  if (!GH_PR_ISSUE_BODY_CMD.test(command)) return;
  const heredoc = GH_HEREDOC.test(command);
  const subst = GH_INLINE_BODY_SUBST.test(command) || GH_BODY_DQ_BACKTICK.test(command);
  if (!heredoc && !subst) return;
  const via = heredoc ? "a heredoc" : "a $(...) command substitution";
  throw new Error(
    `Blocked: gh PR/issue body built with ${via}. Routing the body through the shell mangles it ` +
      "(backtick/`$` expansion, unterminated heredoc) and frequently produces a botched or duplicated body. " +
      "Write the body to a file with the Write tool, then pass it by path: " +
      "`gh pr create ... --body-file /tmp/pr-body.md`. Never inline the body via heredoc or $(...).",
  );
}

function registerCanonicalNativeTools(
  pi: ExtensionAPI,
  isEnabled: (name: string) => boolean,
  isEager: (name: string) => boolean,
) {
  const cwd = process.cwd();
  const jobs = createBashBgJobStore();
  const agentOptions = { getEngine: () => pi.harness.use<AgentEngine>(AGENTS_ENGINE_SERVICE_ID) };

  pi.harness.provide<BashBgJobStore>(BASH_BG_JOBS_SERVICE_ID, jobs, { scope: "process", replace: true });

  // Register helper: skip tools the active profile selection excludes.
  const add = (name: string, definition: object) => {
    if (!isEnabled(name)) return;
    pi.registerTool(definition as Parameters<typeof pi.registerTool>[0]);
  };

  // CACHE CRITICAL: this extension owns the stable first-turn native tool
  // schema set for Luke's Pi profile. Keep this list deterministic and one
  // schema per capability. Dynamic tool decisions belong in tool-search, not
  // in this startup alias layer.
  add("read", {
    ...createReadToolDefinition(cwd, { label: "Read" }),
    alwaysLoad: true,
    replacesBuiltins: ["read"],
  });
  // Rewrite the bash_output/bash_kill mentions in core's Bash description to the
  // unified task_id tools this profile actually ships (TaskOutput/TaskStop).
  const bashDef = createBashToolDefinition(cwd, { label: "Bash" });
  add("bash", {
    ...bashDef,
    description: `${bashDef.description
      ?.replace(/bash_output\(bgId\)/g, "TaskOutput(task_id)")
      .replace(/bash_kill\(bgId\)/g, "TaskStop(task_id)")} Foreground \`sleep\` is blocked — use monitor_start or run_in_background:true instead. Background jobs log full output; don't pipe them through \`tail\`/\`head\` (they buffer until exit). For \`gh pr\`/\`gh issue\` bodies, write the body to a file with the Write tool and pass \`--body-file\` — never inline via heredoc or \`$(...)\`.`,
    // Strip a redundant leading `cd <cwd> &&` so it runs instead of hitting core's
    // "Blocked redundant cd" guard, then reject foreground sleep chains (CC parity).
    // Delegates to any upstream prepareArguments first.
    prepareArguments: (input: unknown) => {
      const args = (bashDef.prepareArguments ? bashDef.prepareArguments(input) : input) as
        | { command?: unknown; run_in_background?: unknown }
        | undefined;
      if (args && typeof args.command === "string") {
        const command = stripRedundantCd(args.command, cwd);
        // Body-mangling guard applies in both fg and bg (PR creation is often backgrounded).
        assertNoFragileGhBody(command);
        if (args.run_in_background === true) assertNoBufferingPipeInBackground(command);
        else assertNoForegroundSleep(command);
        return { ...args, command };
      }
      return args;
    },
    alwaysLoad: true,
    // Core ships BOTH lowercase `bash` and capitalized `Bash` builtins; replace both
    // so this single lowercase `bash` is the only bash schema (no duplicate).
    replacesBuiltins: ["bash", "Bash"],
  });
  // Detach-on-timeout is Luke's opinion, not core's. The fork keeps a neutral
  // default (kill + report timeout); here we opt the Bash tool into Claude
  // Code-style auto-background: a timed-out command keeps running as a bg job,
  // readable via TaskOutput and stoppable via TaskStop. `t.background()` adopts
  // the live process into the same bg registry these tools already read.
  //
  // Install once as a process-wide preference and NEVER restore it on session
  // dispose. `onBashTimeout` mutates a single package-global resolver, and its
  // restore fns are not a real stack — restoring on every top-level dispose
  // (/new, /fork, switchSession) reverted the global to the core kill policy,
  // so a timed-out command was KILLED instead of detached until the next session
  // re-activated this extension (and stacked disposes clobbered it to kill
  // outright). The policy is idempotent — always the same detach closure — so
  // re-installing on each activation and never restoring keeps auto-background
  // reliably on. Regression: autobg-lifecycle.test.mjs.
  if (isEnabled("bash")) {
    onBashTimeout((t) => ({ backgroundedJobId: t.background().id }));
  }
  // CACHE CRITICAL: these utility aliases must remain provider-visible but
  // schema-deferred. Marking them alwaysLoad reintroduces the prompt-cache burst
  // where background/listing schemas are billed every turn. They are discovered
  // through the stable <deferred-tools> index and loaded through Anthropic
  // `defer_loading` / `tool_reference`, matching Claude Code and Codex.
  // Unified background-task tools over the core task-registry seam: one id space
  // across background bash jobs AND background agent runs. Output is push-notified
  // and read from output paths with Read; TaskBackgroundList discovers those paths.
  add("TaskBackgroundList", {
    ...createTaskBackgroundListToolDefinition(),
    ...deferredOrEager(isEager("TaskBackgroundList")),
    replacesBuiltins: ["bash_output"],
  });
  add("TaskStop", {
    ...createTaskStopToolDefinition(),
    ...deferredOrEager(isEager("TaskStop")),
    replacesBuiltins: ["bash_kill"],
  });
  add("edit", {
    ...withEditArgumentRepair(createEditToolDefinition(cwd, { label: "Edit" }), cwd),
    alwaysLoad: true,
    replacesBuiltins: ["edit"],
  });
  add("write", {
    ...createWriteToolDefinition(cwd, { label: "Write" }),
    alwaysLoad: true,
    replacesBuiltins: ["write"],
  });
  add("Agent", {
    ...createUppercaseAgentToolDefinition("", agentOptions),
    alwaysLoad: true,
  });
  add("grep", {
    ...createGrepToolDefinition(cwd, { label: "Grep" }),
    alwaysLoad: true,
    replacesBuiltins: ["grep"],
  });
  // Core registers this builtin capitalized ("Glob", the lone capitalized
  // file/shell tool); replacesBuiltins is matched case-sensitively, so it must be
  // "Glob" to drop the base builtin (the config-gate key below stays lowercase).
  add("glob", {
    ...withGlobDefaultLimit(createGlobToolDefinition(cwd, { label: "Glob" })),
    deferLoading: true,
    replacesBuiltins: ["Glob"],
  });
  add("ls", {
    ...createLsToolDefinition(cwd, { label: "Ls" }),
    deferLoading: true,
    replacesBuiltins: ["ls"],
  });

  pi.onSessionDispose(() => {
    jobs.killAll();
  });
}

export default function nativeToolOverridesExtension(pi: ExtensionAPI) {
  // CACHE CRITICAL: override Pi core's default load actions before this profile
  // registers Luke's native alias schemas. This keeps the system prompt/tools prefix
  // stable and prevents duplicate capability schemas (`agent`/`Agent`/`Task`,
  // `bash_output`/`BashOutput`, etc.) from being billed every turn.
  pi.hooks.removeAction(LOAD_HOOK, "agents");
  pi.hooks.removeAction(LOAD_HOOK, "bashBgJobs");

  const selection = loadSelection();
  const isEnabled = makeIsEnabled(selection);
  const isEager = makeIsEager(selection);
  registerCanonicalNativeTools(pi, isEnabled, isEager);
  registerWebFetch(pi, isEnabled);
  registerWebSearch(pi, isEnabled);

